const DRIVE_FOLDER_NAME = 'Trading Transcripts';
const DRIVE_FOLDER_ID = '1InBLV4SvbDj4_mhsNk_D7VZR3un-Bp5q';
const YT_DLP_VERSION = '2026.10.26';
const SHORT_TRANSCRIPT_CHARS = 2000;
const LONG_VIDEO_SECONDS = 600;

const PROVIDERS = {
