  claimSql: creditClaimQuery(summary.monthStart, summary.limit),
  warningText: 'TRANSCRIPT CREDITS - monthly usage is ' + row.credits_used + ' of ' + summary.limit + ' (80% of MONTHLY_TRANSCRIPT_LIMIT).',
